// BEGIN EMBEDDED WOODEN PIECES
const woodPieceImages = {"wK":"data:image/png;base64,","wQ":"data:image/png;base64,","wR":"data:image/png;base64,","wB":"data:image/png;base64,","wN":"data:image/png;base64,","wP":"data:image/png;base64,","bK":"data:image/png;base64,","bQ":"data:image/png;base64,","bR":"data:image/png;base64,","bB":"data:image/png;base64,","bN":"data:image/png;base64,","bP":"data:image/png;base64,"};
const flatPieceImages = {"wK":"data:image/svg+xml;base64,","wQ":"data:image/svg+xml;base64,","wR":"data:image/svg+xml;base64,","wB":"data:image/svg+xml;base64,","wN":"data:image/svg+xml;base64,","wP":"data:image/svg+xml;base64,","bK":"data:image/svg+xml;base64,","bQ":"data:image/svg+xml;base64,","bR":"data:image/svg+xml;base64,","bB":"data:image/svg+xml;base64,","bN":"data:image/svg+xml;base64,","bP":"data:image/svg+xml;base64,"};
// END EMBEDDED WOODEN PIECES
window.chessscopePieceImages = flatPieceImages;

// Keep sound synthesis in the main module so board rendering never depends on
// a second JavaScript request succeeding.
const soundscape = (() => {
  const KEY = 'chessscope-sounds';
  let enabled = true;
  try { enabled = localStorage.getItem(KEY) !== 'off'; } catch {}
  let context, noiseBuffer;
  function audio() {
    if (!enabled) return null;
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    context ||= new AudioContextClass();
    if (context.state === 'suspended') context.resume().catch(() => {});
    return context;
  }
  function noise(ctx) {
    if (noiseBuffer) return noiseBuffer;
    const length = Math.ceil(ctx.sampleRate * .12);
    noiseBuffer = ctx.createBuffer(1,length,ctx.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i=0;i<length;i++) data[i] = (Math.random()*2-1) * (1-i/length);
    return noiseBuffer;
  }
  function tone(ctx, hz, delay=0, duration=.2, volume=.07, type='sine', endHz=hz) {
    const now = ctx.currentTime + delay;
    const osc = ctx.createOscillator(), gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(hz,now);
    if (endHz !== hz) osc.frequency.exponentialRampToValueAtTime(Math.max(30,endHz),now+duration);
    gain.gain.setValueAtTime(.0001,now);
    gain.gain.exponentialRampToValueAtTime(Math.max(.001,volume),now+.012);
    gain.gain.exponentialRampToValueAtTime(.0001,now+duration);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now);
    osc.stop(now+duration+.02);
  }
  function wood(ctx, delay=0, weight=1, base=170) {
    const now = ctx.currentTime+delay;
    const source=ctx.createBufferSource(), filter=ctx.createBiquadFilter(), gain=ctx.createGain();
    source.buffer=noise(ctx);
    filter.type='lowpass';
    filter.frequency.value=900+Math.random()*350;
    gain.gain.setValueAtTime(.0001,now);
    gain.gain.exponentialRampToValueAtTime(.07*weight,now+.003);
    gain.gain.exponentialRampToValueAtTime(.0001,now+.085);
    source.connect(filter).connect(gain).connect(ctx.destination);
    source.start(now);
    source.stop(now+.1);
    tone(ctx,base,delay,.095,.042*weight,'sine',base*.62);
  }
  let lastTick=0;
  return {
    get enabled() { return enabled; },
    toggle() {
      enabled=!enabled;
      try { localStorage.setItem(KEY,enabled?'on':'off'); } catch {}
      return enabled;
    },
    play(kind) {
      const ctx=audio();
      if (!ctx) return;
      const j=1+(Math.random()-0.5)*0.06;
      if (kind==='move') wood(ctx,0,1,165+Math.random()*20);
      if (kind==='select') tone(ctx,620*j,0,.06,.028,'triangle');
      if (kind==='start') { wood(ctx); [392,523,659].forEach((hz,i)=>tone(ctx,hz*j,.08+i*.09,.3,.05,'triangle')); }
      if (kind==='win') { wood(ctx,0,1.2); [523,659,784,1047].forEach((hz,i)=>tone(ctx,hz*j,.08+i*.11,.5,.05,'sine')); }
      if (kind==='lose') { wood(ctx,0,1.2); [392,330,262,196].forEach((hz,i)=>tone(ctx,hz*j,.08+i*.13,.4,.05,'triangle')); }
      if (kind==='draw') { wood(ctx); tone(ctx,440*j,.08,.25,.05,'sine'); tone(ctx,440*j,.3,.3,.04,'sine'); }
      if (kind==='illegal') tone(ctx,150*j,0,.12,.05,'square',110);
      if (kind==='lift') tone(ctx,300*j,0,.09,.035,'sine',520*j);
      if (kind==='drop') { wood(ctx,0,.45,150); tone(ctx,220*j,.02,.08,.03,'sine',160); }
      if (kind==='tick') { if (ctx.currentTime-lastTick<0.3) return; lastTick=ctx.currentTime; tone(ctx,1250*j,0,.035,.014,'sine'); }
      if (kind==='complete') { wood(ctx,0,.8); [659,784,1047].forEach((hz,i)=>tone(ctx,hz*j,.07+i*.1,.5,.05,'sine')); }
      if (kind==='capture') { wood(ctx,0,1.15); wood(ctx,.075,.52); }
      if (kind==='check') { wood(ctx); tone(ctx,680,.07,.24,.06,'triangle'); }
      if (kind==='free') { wood(ctx,0,1.2); tone(ctx,880,.075,.22,.055); tone(ctx,1175,.16,.36,.045); }
      if (kind==='inaccuracy') { wood(ctx); tone(ctx,380,.08,.18,.04,'triangle',325); tone(ctx,310,.22,.16,.027,'triangle',285); }
      if (kind==='mistake') { wood(ctx,0,1.3); tone(ctx,310,.07,.23,.052,'triangle',230); tone(ctx,220,.24,.25,.04,'triangle',145); }
      if (kind==='blunder') { wood(ctx,0,1.6); tone(ctx,220,.05,.34,.072,'sawtooth',82); tone(ctx,155,.20,.39,.045,'triangle',65); }
      if (kind==='brilliant') { wood(ctx,0,.7); [587,740,880,1175].forEach((hz,i)=>tone(ctx,hz,.06+i*.09,.52,.042,'sine')); }
      if (kind==='great') { wood(ctx,0,.8); tone(ctx,523,.07,.30,.044,'triangle'); tone(ctx,784,.19,.44,.048,'sine'); }
      if (kind==='mate') { wood(ctx,0,1.3); [392,494,587].forEach((hz,i)=>tone(ctx,hz,.06+i*.14,.7,.065,'triangle')); tone(ctx,784,.56,1.15,.065,'sine'); }
    }
  };
})();
window.chessscopePlaySound = kind => soundscape.play(kind);

const $ = id => document.getElementById(id);
const pieceNames = { K:'king', Q:'queen', R:'rook', B:'bishop', N:'knight', P:'pawn' };
const fallbackSymbols = { K:'♔', Q:'♕', R:'♖', B:'♗', N:'♘', P:'♙', k:'♚', q:'♛', r:'♜', b:'♝', n:'♞', p:'♟' };
const glyphs = { brilliant:'!!', great:'!', best:'★', excellent:'✓', good:'', inaccuracy:'?!', mistake:'?', blunder:'??' };
const descriptions = { brilliant:'A strong piece offer that Stockfish prefers.', great:'A critical move that was much stronger than the next best option.', best:'The engine’s top choice in this position.', excellent:'A precise move that keeps the advantage.', good:'A sound move with little change in evaluation.', inaccuracy:'A small missed opportunity.', mistake:'A significant change in the position.', blunder:'A decisive loss of winning chances.' };
let game = null, pgn = '', analysis = new Map(), initialEval = null, currentPly = 0, flipped = false, playing = null, analyzing = false, activeTab = 'moves', abortController = null;
let openingInfo = null;
let boardTheme = 'classic';
try { if (localStorage.getItem('chessscope-board-theme') === 'wood') boardTheme = 'wood'; } catch {}
let toastTimer;

function escapeHtml(value) { return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
function scoreText(e) {
  if (!e) return '—';
  if (e.mate !== null) return `${e.mate > 0 ? '+' : '−'}M${Math.abs(e.mate)}`;
  return (e.cp >= 0 ? '+' : '−') + (Math.abs(e.cp)/100).toFixed(1);
}
function winChance(e, side) {
  if (!e) return 50;
  const cp = e.mate !== null ? (e.mate > 0 ? 1500 : -1500) : e.cp;
  return 100/(1+Math.exp(-(side === 'w' ? cp : -cp)/130));
}
function accuracy(side) {
  if (!game) return null;
  const played = game.moves.filter(m => m.color === side && analysis.has(m.ply));
  if (!played.length) return null;
  const losses = played.map(m => analysis.get(m.ply).classification.loss);
  return Math.max(0,Math.min(100,Math.round(100 - losses.reduce((a,b)=>a+b,0)/losses.length*1.55)));
}
function currentEvaluation() { return currentPly === 0 ? initialEval : analysis.get(currentPly)?.evaluation; }
function squareToPoint(s) {
  const file = 'abcdefgh'.indexOf(s[0]), rank = 8-Number(s[1]);
  const x = flipped ? 7-file : file, y = flipped ? 7-rank : rank;
  return [x*100+50,y*100+50];
}
function arrow(from,to,color) {
  const [x1,y1] = squareToPoint(from), [x2,y2] = squareToPoint(to);
  const dx = x2-x1, dy = y2-y1, length = Math.hypot(dx,dy), ux = dx/length, uy = dy/length;
  const endX = x2-ux*26, endY = y2-uy*26, stemX = endX-ux*19, stemY = endY-uy*19;
  const sideX = -uy*13, sideY = ux*13;
  return `<line x1="${x1}" y1="${y1}" x2="${stemX}" y2="${stemY}" stroke="${color}" stroke-width="15" stroke-linecap="round" opacity=".7"/><polygon points="${endX},${endY} ${stemX+sideX},${stemY+sideY} ${stemX-sideX},${stemY-sideY}" fill="${color}" opacity=".75"/>`;
}
function renderBoard() {
  document.querySelector('.board-container')?.classList.toggle('classic',boardTheme==='classic');
  const fen = currentPly === 0 ? (game?.initialFen || 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1') : game.moves[currentPly-1].fen;
  const rows = fen.split(' ')[0].split('/'), pieces = [];
  rows.forEach(row => { for (const char of row) if (/\d/.test(char)) pieces.push(...Array(Number(char)).fill('')); else pieces.push(char); });
  const selected = currentPly ? game.moves[currentPly-1] : null;
  const classification = analysis.get(currentPly)?.classification.label;
  const checkedSide = selected && /[+#]/.test(selected.san) ? fen.split(' ')[1] : null;
  const checkedKing = checkedSide ? pieces.indexOf(checkedSide==='w'?'K':'k') : -1;
  const isMate = Boolean(selected?.san.includes('#'));
  const loserKing = isMate ? checkedKing : -1;
  const winnerKing = isMate ? pieces.indexOf(fen.split(' ')[1]==='w'?'k':'K') : -1;
  const indexes = [...Array(64).keys()];
  if (flipped) indexes.reverse();
  $('board').innerHTML = indexes.map((i,displayIndex) => {
    const rank = Math.floor(i/8), file = i%8, sq = 'abcdefgh'[file]+(8-rank), piece = pieces[i], light = (rank+file)%2===0;
    const coordRank = displayIndex%8===0 ? `<span class="coordinate rank">${8-rank}</span>` : '';
    const coordFile = Math.floor(displayIndex/8)===7 ? `<span class="coordinate file">${'abcdefgh'[file]}</span>` : '';
    const side = piece && piece===piece.toUpperCase() ? 'w' : 'b';
    const sprite = (boardTheme==='classic' ? flatPieceImages : woodPieceImages)[side+piece.toUpperCase()];
    const badge = selected?.to===sq && classification && ['brilliant','great','best','blunder','mistake','inaccuracy'].includes(classification)
      ? `<span class="square-badge ${classification}">${classification==='best'?'★':glyphs[classification]}</span>` : '';
    return `<div class="square ${light?'light':'dark'} ${selected?.from===sq?'last-from':''} ${selected?.to===sq?'last-to':''} ${i===checkedKing&&!isMate?'in-check':''} ${i===loserKing?'mate-loser':''} ${i===winnerKing?'mate-winner':''}" data-square="${sq}">${coordRank}${piece?`<span class="piece-fallback ${side==='w'?'white':'black'}">${fallbackSymbols[piece]}</span>${sprite?`<img class="piece-img" src="${sprite}" alt="${side==='w'?'White':'Black'} ${pieceNames[piece.toUpperCase()]}" draggable="false">`:''}`:''}${i===checkedKing?'<span class="check-alert">!</span>':''}${badge}${coordFile}</div>`;
  }).join('');
  for (const image of $('board').querySelectorAll('.piece-img')) {
    const fallback = image.previousElementSibling;
    if (image.complete && image.naturalWidth) fallback.hidden = true;
    else {
      image.addEventListener('load',()=>{ fallback.hidden = true; },{once:true});
      image.addEventListener('error',()=>{ image.remove(); },{once:true});
    }
  }
  let arrows = '';
  if (selected) arrows += arrow(selected.from,selected.to,'#e3db67');
  const best = analysis.get(currentPly)?.bestMove;
  if (best && selected && best.uci !== selected.uci) arrows += arrow(best.from,best.to,'#4bc1bb');
  $('board-arrows').innerHTML = arrows;
  const e = currentEvaluation();
  const pct = Math.max(5,Math.min(95,100-winChance(e,'w')));
  $('eval-fill').style.height = `${pct}%`;
  $('eval-rail-text').textContent = scoreText(e);
  $('move-indicator').textContent = selected ? `${selected.moveNumber}${selected.color==='w'?'.':'...'} ${selected.san}` : 'Starting position';
  $('playback-count').textContent = `Move ${currentPly} of ${game?.moves.length || 0}`;
  for (const id of ['first-move','prev-move']) $(id).disabled = currentPly===0;
  for (const id of ['next-move','last-move']) $(id).disabled = !game || currentPly===game.moves.length;
  const note = $('board-note');
  if (!selected) note.innerHTML = '<span>✦</span><div><strong>Welcome to the analysis board</strong><p>Follow the game from the first move. Gold shows the played move; teal shows Stockfish’s preferred move when they differ.</p></div>';
  else {
    const info = analysis.get(currentPly), label = info?.classification.label || 'analyzing';
    note.innerHTML = `<span>${label==='brilliant'?'✦':label==='blunder'?'!':'↗'}</span><div><strong>${escapeHtml(selected.moveNumber+(selected.color==='w'?'. ':'... ')+selected.san)} ${label==='analyzing'?'· Engine is thinking':`· ${label[0].toUpperCase()+label.slice(1)} move`}</strong><p>${escapeHtml(info ? descriptions[label] : 'Stockfish is reviewing this move.')} ${info?.classification.freePiece ? `The ${pieceNames[selected.captured]} was unprotected. ` : ''}${info && info.bestMove?.uci !== selected.uci ? `Stockfish preferred ${escapeHtml(info.bestMove.san)} (teal arrow).` : ''}${info?.evaluation.line?.length ? ` Next: ${escapeHtml(info.evaluation.line.join(' '))}.` : ''}</p></div>`;
  }
  document.querySelectorAll('.move-cell').forEach(el => el.classList.toggle('active',Number(el.dataset.ply)===currentPly));
}
function renderMoves() {
  if (!game) { $('moves-list').innerHTML = '<div class="empty-list">Your move list will appear here.</div>'; return; }
  const rows = [];
  for (let i=0;i<game.moves.length;i+=2) {
    const cells = game.moves.slice(i,i+2).map(m => {
      const a = analysis.get(m.ply), label = a?.classification.label;
      return `<button class="move-cell ${currentPly===m.ply?'active':''}" data-ply="${m.ply}" title="${label?label+' move':'View position'}"><span class="move-san">${escapeHtml(m.san)}</span>${m.clock?`<small class="move-clock">${escapeHtml(m.clock)}</small>`:''}${a?.classification.freePiece?'<span class="free-badge" title="Unprotected piece captured">FREE</span>':''}${label?`<span class="badge ${label}">${glyphs[label]}</span>`:''}</button>`;
    });
    const last = game.moves[Math.min(i+1,game.moves.length-1)], evaluation=analysis.get(last.ply)?.evaluation;
    rows.push(`<div class="move-row"><span class="move-number">${game.moves[i].moveNumber}.</span>${cells.join('')}${cells.length===1?'<span></span>':''}<span class="row-eval">${scoreText(evaluation)}<small>${evaluation?.depth?`d${evaluation.depth}`:''}</small></span></div>`);
  }
  $('moves-list').innerHTML = rows.join('');
  $('moves-count').textContent = `${game.moves.length} MOVES`;
}
function renderChart() {
  const svg = $('eval-chart');
  const entries = [initialEval,...(game?.moves || []).map(m => analysis.get(m.ply)?.evaluation)];
  const points = entries.map((e,i) => e ? [i/Math.max(1,entries.length-1)*500,60-Math.max(-500,Math.min(500,e.mate!==null?(e.mate>0?500:-500):e.cp))/500*53] : null).filter(Boolean);
  const path = points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
  const area = points.length ? `${path} L${points.at(-1)[0]} 120 L0 120 Z` : '';
  const marker = points[currentPly];
  svg.innerHTML = `<defs><linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c9e981" stop-opacity=".28"/><stop offset="1" stop-color="#c9e981" stop-opacity="0"/></linearGradient></defs><line x1="0" y1="7" x2="500" y2="7" stroke="#3a4950" stroke-dasharray="3 5"/><line x1="0" y1="60" x2="500" y2="60" stroke="#61715a" stroke-dasharray="4 5"/><line x1="0" y1="113" x2="500" y2="113" stroke="#3a4950" stroke-dasharray="3 5"/>${area?`<path d="${area}" fill="url(#chartGradient)"/><path d="${path}" fill="none" stroke="#cae878" stroke-width="2.5" vector-effect="non-scaling-stroke"/>`:''}${marker?`<circle cx="${marker[0]}" cy="${marker[1]}" r="5" fill="#d9f2a1" stroke="#53613d" stroke-width="2"/>`:''}`;
  $('chart-progress').textContent = analyzing ? `Analyzing ${analysis.size}/${game?.moves.length || 0}` : game ? 'Analysis complete' : 'Waiting for game';
}
function renderInsights() {
  if (!game) { $('coach-list').innerHTML = '<div class="empty-list">Move explanations will appear after analysis.</div>'; return; }
  const counts = {brilliant:0,great:0,best:0,mistake:0,blunder:0};
  for (const a of analysis.values()) if (counts[a.classification.label]!==undefined) counts[a.classification.label]++;
  const moments = game.moves.filter(m => ['brilliant','great','blunder','mistake'].includes(analysis.get(m.ply)?.classification.label)).sort((a,b) => {
    const aa = analysis.get(a.ply), bb = analysis.get(b.ply);
    return (bb.classification.label==='brilliant'?100:bb.classification.label==='great'?50:bb.classification.loss)-(aa.classification.label==='brilliant'?100:aa.classification.label==='great'?50:aa.classification.loss);
  }).slice(0,5);
  const move=game.moves[currentPly-1], info=analysis.get(currentPly), label=info?.classification.label;
  $('coach-list').innerHTML = `<div class="insight-summary"><h3>${move?`${move.moveNumber}${move.color==='w'?'.':'...'} ${escapeHtml(move.san)}`:'Your game at a glance'}</h3><p>${move ? escapeHtml(info ? descriptions[label] : 'Stockfish is still reviewing this move.') : 'Select a move to ask what changed, which move the engine liked, and what to look for next.'}</p></div><div class="coach-prompts"><button data-coach="why">What changed?</button><button data-coach="better">What was better?</button><button data-coach="think">How should I think?</button></div><div class="coach-answer" id="coach-answer">Select a question above for a position-specific explanation.</div><div class="insight-stat-grid">${Object.entries(counts).map(([key,value])=>`<div class="insight-stat"><strong>${value}</strong><span>${key.toUpperCase()}</span></div>`).join('')}</div>${moments.length?moments.map(m=>`<div class="moment" data-ply="${m.ply}"><div><strong>${m.moveNumber}${m.color==='w'?'.':'...'} ${escapeHtml(m.san)} · ${analysis.get(m.ply).classification.label}</strong><p>${escapeHtml(descriptions[analysis.get(m.ply).classification.label])}</p></div><span>→</span></div>`).join(''):'<div class="empty-list">Key moments will appear as the engine analyzes.</div>'}`;
}
function openingAtPly(ply) {
  if (!game?.moves?.length) return null;
  const count = Math.max(1, Math.min(game.moves.length, ply || game.moves.length));
  const slice = game.moves.slice(0, count);
  return window.chessscopeIdentifyOpening?.(slice) || openingInfo || null;
}
function variationText(info) {
  if (!info) return 'Main line';
  return [info.variation || 'Main line', info.family].filter(Boolean).join(' · ');
}
function renderInfo() {
  if (!game) { $('info-list').innerHTML='<div class="empty-list">PGN details will appear here.</div>'; return; }
  const h=game.headers, rows=[['White',h.White],['Black',h.Black],['Result',h.Result],['Event',h.Event],['Date',h.Date],['Site',h.Site],['Time control',h.TimeControl],['Opening',h.Opening || openingInfo?.name],['Variation',openingInfo?.variation && openingInfo.variation!=='Main line' ? openingInfo.variation : variationText(openingInfo)]];
  $('info-list').innerHTML=`<div class="insight-summary"><h3>Game information</h3><p>Names and metadata are read directly from this PGN.</p></div><div class="info-table">${rows.filter(([,value])=>value).map(([name,value])=>`<div><span>${escapeHtml(name)}</span><strong>${escapeHtml(value)}</strong></div>`).join('')}</div>`;
}
function renderOpening() {
  const banner=$('analysis-opening'), bannerName=$('analysis-opening-name'), bannerVariation=$('analysis-variation-name');
  if (!game) {
    $('openings-list').innerHTML='<div class="empty-list">Import a PGN to identify its opening.</div>';
    $('timeline-opening').textContent='Opening appears after you import a game.';
    banner?.classList.add('hidden');
    return;
  }
  const h=game.headers, full=openingInfo, current=openingAtPly(currentPly) || full;
  const fullName=h.Opening || full?.name || 'Opening not identified';
  const currentLabel=current?.name || fullName;
  const currentVariation=current?.variation || full?.variation || 'Main line';
  banner?.classList.remove('hidden');
  if (bannerName) bannerName.textContent=fullName;
  if (bannerVariation) bannerVariation.textContent=variationText({...full,variation:openingAtPly(game.moves.length)?.variation || full?.variation}) + (currentPly && currentPly!==game.moves.length && current ? ` · at move ${currentPly}: ${currentLabel} — ${currentVariation}` : '');
  $('timeline-opening').textContent=`${currentLabel} — ${currentVariation}`;
  $('openings-list').innerHTML=`<div class="insight-summary"><div class="eyebrow small">OPENING IDENTIFICATION</div><h3>${escapeHtml(fullName)}</h3><p>${escapeHtml(full?.variation || 'Main line')} · ${escapeHtml(full?.family || 'Game opening')} · ${game.moves.length} half-moves in this game</p></div><div class="opening-review"><strong>The plan</strong><p>${escapeHtml(full?.idea || 'Develop your pieces, control the center, and secure your king before launching an attack.')}</p><strong>What to watch</strong><p>${escapeHtml(full?.watch || 'Look for checks, captures, and threats before following a memorized move.')}</p>${full?.id?`<button class="secondary-button" id="practice-this-opening" data-opening="${full.id}">Practice this opening →</button>`:''}</div>`;
}
function renderSummary() {
  $('analysis-empty').classList.toggle('hidden',Boolean(game));
  $('match-banner').classList.toggle('hidden',!game);
  $('copy-pgn').classList.toggle('hidden',!game);
  if (!game) {
    $('sidebar-game').textContent='No game loaded';
    $('sidebar-date').textContent='Upload a PGN to start';
    $('white-accuracy').textContent='—';
    $('black-accuracy').textContent='—';
    return;
  }
  const h = game.headers;
  $('white-name').textContent = h.White || 'White player';
  $('black-name').textContent = h.Black || 'Black player';
  $('white-elo').textContent = h.WhiteElo ? `${h.WhiteElo} ELO` : 'WHITE PIECES';
  $('black-elo').textContent = h.BlackElo ? `${h.BlackElo} ELO` : 'BLACK PIECES';
  const result=h.Result || '—', winner=result==='1-0'?h.White:result==='0-1'?h.Black:null;
  $('result').textContent = winner ? `${winner} wins` : result==='1/2-1/2' ? 'Draw' : `${h.White || 'White'} vs ${h.Black || 'Black'}`;
  $('game-meta').textContent = [result,h.Event,h.Date?.replace(/\.\?\?/g,'')].filter(Boolean).join(' · ') || 'Imported game';
  $('sidebar-game').textContent = `${h.White || 'White'} vs ${h.Black || 'Black'}`;
  $('sidebar-date').textContent = h.Event || 'Imported PGN';
  $('white-accuracy').textContent = accuracy('w')===null ? '—' : `${accuracy('w')}%`;
  $('black-accuracy').textContent = accuracy('b')===null ? '—' : `${accuracy('b')}%`;
}
function renderAll() { renderBoard(); renderMoves(); renderChart(); renderInsights(); renderInfo(); renderOpening(); renderSummary(); }
function goTo(ply) {
  if (!game) return;
  const previous = currentPly;
  currentPly = Math.max(0,Math.min(game.moves.length,ply));
  renderBoard(); renderChart(); renderInsights(); renderOpening();
  const active = document.querySelector('.move-cell.active');
  active?.scrollIntoView({block:'nearest'});
  if (currentPly !== previous && currentPly > 0) {
    const move = game.moves[currentPly-1], info = analysis.get(currentPly);
    if(currentPly===previous+1)window.chessscopeAnimateLanding?.('board',move.from,move.to);
    const label = info?.classification.label;
    const sound = move.san.includes('#') ? 'mate' : label==='brilliant' ? 'brilliant' : label==='great' ? 'great'
      : label==='blunder' ? 'blunder' : label==='mistake' ? 'mistake'
      : label==='inaccuracy' ? 'inaccuracy' : info?.classification.freePiece ? 'free'
      : move.san.includes('+') ? 'check' : move.captured ? 'capture' : 'move';
    soundscape.play(sound);
    const toast = $('move-toast');
    toast.textContent = move.san.includes('#') ? 'CHECKMATE' : info?.classification.freePiece && !['brilliant','great','blunder','mistake','inaccuracy'].includes(label) ? 'FREE PIECE' : label ? `${label.toUpperCase()} MOVE` : move.captured ? 'CAPTURE' : 'MOVE PLAYED';
    toast.className = `move-toast ${sound} visible`;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>toast.classList.remove('visible'),1250);
  }
}
function stopPlayback() { if (playing) clearInterval(playing); playing=null; $('toggle-play').textContent='▶'; }
async function analyzePgn(source) {
  stopPlayback(); abortController?.abort();
  analysis = new Map(); initialEval=null; currentPly=0; game=null; openingInfo=null; pgn=source; analyzing=true;
  renderSummary();
  $('chart-progress').textContent = 'Reading PGN';
  $('modal-error').textContent = '';
  abortController = new AbortController();
  try {
    const response = await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pgn:source}),signal:abortController.signal});
    if (!response.ok) { const data=await response.json(); throw Error(data.error || 'Could not analyze the PGN.'); }
    $('import-dialog').close();
    const reader = response.body.getReader(), decoder = new TextDecoder();
    let buffer='';
    while (true) {
      const {done,value}=await reader.read();
      if (done) break;
      buffer += decoder.decode(value,{stream:true});
      let end;
      while ((end=buffer.indexOf('\n'))!==-1) {
        const line=buffer.slice(0,end); buffer=buffer.slice(end+1);
        if (!line) continue;
        const event=JSON.parse(line);
        if (event.type==='game') { game=event.game; openingInfo=window.chessscopeIdentifyOpening?.(game.moves)||null; renderAll(); }
        else if (event.type==='initial') { initialEval=event.evaluation; renderBoard(); renderChart(); }
        else if (event.type==='move') {
          analysis.set(event.ply,event);
          soundscape.play('tick');
          renderMoves(); renderSummary(); renderInsights(); renderChart();
          if (currentPly===event.ply || (currentPly===0 && event.ply===1)) renderBoard();
        }
        else if (event.type==='error') throw Error(event.error);
        else if (event.type==='complete') { analyzing=false; soundscape.play('complete'); renderChart(); }
      }
    }
  } catch(error) {
    if (error.name==='AbortError') return;
    analyzing=false;
    $('chart-progress').textContent='Engine unavailable';
    $('board-note').innerHTML=`<span>!</span><div><strong>Analysis stopped</strong><p>${escapeHtml(error.message)}</p></div>`;
    if ($('import-dialog').open) $('modal-error').textContent=error.message;
  } finally { analyzing=false; renderChart(); }
}

function openImport() { $('pgn-input').value=game?'':pgn; $('modal-error').textContent=''; if(!$('import-dialog').open)$('import-dialog').showModal(); $('pgn-input').focus(); }
$('nav-import').addEventListener('click',openImport);
