// ---- Saved games library (localStorage) + .pgn download ----
const SAVED_KEY='chessscope-saved-games';
function loadSavedGames() { try { return JSON.parse(localStorage.getItem(SAVED_KEY)||'[]'); } catch { return []; } }
function storeSavedGames(list) { try { localStorage.setItem(SAVED_KEY,JSON.stringify(list)); } catch {} }
function savedGameName(source) {
  const white=source.match(/\[White\s+"([^"]+)"/)?.[1]||'White', black=source.match(/\[Black\s+"([^"]+)"/)?.[1]||'Black';
  const date=source.match(/\[Date\s+"([^"]+)"/)?.[1]||'';
  return `${white} vs ${black}${date && !date.includes('??') ? ' · '+date : ''}`.slice(0,90);
}
function refreshSavedUI() {
  const list=loadSavedGames(), box=$('saved-list'), count=$('saved-count');
  if (count) count.textContent=String(list.length);
  if (!box) return;
  box.innerHTML=list.length?list.map((item,i)=>`<div class="saved-item"><button type="button" data-saved-load="${i}"><strong>${escapeHtml(item.name)}</strong><span>${escapeHtml(item.date||'Saved game')} · ${escapeHtml(String(item.pgn.length>9000?(item.pgn.length/1024).toFixed(0)+' KB':item.pgn.length+' chars'))}</span></button><button type="button" class="saved-delete" data-saved-delete="${i}" title="Delete">×</button></div>`).join(''):'<div class="empty-list">No saved games yet. Analyze a game, then press Save.</div>';
}
function updateSaveButton() {
  const el=$('save-game');
  if (!el) return;
  el.classList.toggle('hidden',!game);
  const saved=loadSavedGames().some(item=>item.pgn===pgn);
  el.innerHTML=saved?'✓ <span>Saved</span>':'♡ <span>Save</span>';
}
$('save-game')?.addEventListener('click',()=>{
  if (!game || !pgn) return;
  const list=loadSavedGames();
  if (list.some(item=>item.pgn===pgn)) { $('modal-error').textContent=''; openImport(); document.querySelector('[data-import-tab="saved"]')?.click(); return; }
  list.unshift({ name:savedGameName(pgn), date:new Date().toISOString().slice(0,10), pgn });
  storeSavedGames(list.slice(0,60));
  refreshSavedUI(); updateSaveButton();
  const el=$('save-game'); el.innerHTML='✓ <span>Saved</span>';
});
$('download-pgn')?.addEventListener('click',()=>{
  if (!game || !pgn) return;
  const blob=new Blob([pgn],{type:'application/x-chess-pgn'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download='chessscope-game.pgn';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(()=>URL.revokeObjectURL(a.href),2000);
});
$('saved-list')?.addEventListener('click',event=>{
  const load=event.target.closest('[data-saved-load]'), del=event.target.closest('[data-saved-delete]');
  if (del) { const list=loadSavedGames(); list.splice(Number(del.dataset.savedDelete),1); storeSavedGames(list); refreshSavedUI(); return; }
  if (load) { const item=loadSavedGames()[Number(load.dataset.savedLoad)]; if (item) { $('pgn-input').value=item.pgn; analyzePgn(item.pgn); } }
});
