document.querySelector('.import-tabs')?.addEventListener('click',event=>{
  const tab=event.target.closest('[data-import-tab]');
  if (!tab) return;
  for (const name of ['paste','chesscom','saved']) {
    document.querySelector(`[data-import-tab="${name}"]`)?.classList.toggle('active',name===tab.dataset.importTab);
    $(`import-pane-${name}`)?.classList.toggle('hidden',name!==tab.dataset.importTab);
  }
  if (tab.dataset.importTab==='saved') refreshSavedUI();
});
function chesscomLabel(g) {
  const white=g.white?.username||'White', black=g.black?.username||'Black';
  const result=g.white?.result==='win'?'1-0':g.black?.result==='win'?'0-1':'½-½';
  const tc=g.time_control||'';
  return { title:`${white} vs ${black} · ${result}`, meta:`${tc} · ${g.rated?'Rated':'Casual'}` };
}
function chesscomDayLabel(end_time) {
  if (!end_time) return 'Earlier';
  const d=new Date(end_time*1000), now=new Date(), day=x=>x.getFullYear()+'-'+x.getMonth()+'-'+x.getDate();
  if (day(d)===day(now)) return 'Today';
  const yesterday=new Date(now); yesterday.setDate(now.getDate()-1);
  if (day(d)===day(yesterday)) return 'Yesterday';
  return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
}
let chesscomGames=[];
// Delegated once: game buttons are recreated on every search, and every button
// needs type="button" so it never submits the <form method="dialog"> (that submit
// was closing the dialog and swallowing the click — the "nothing happens" bug).
$('chesscom-list')?.addEventListener('click',event=>{
  const button=event.target.closest('[data-chesscom]');
  if (!button) return;
  event.preventDefault();
  const g=chesscomGames[Number(button.dataset.chesscom)];
  if (g?.pgn) { $('pgn-input').value=g.pgn; analyzePgn(g.pgn); }
  else $('modal-error').textContent='That game has no PGN attached.';
});
$('chesscom-fetch')?.addEventListener('click',async()=>{
  const username=$('chesscom-username').value.trim().toLowerCase().replace(/^.*chess\.com\/member\//,'').replace(/[^a-z0-9_-]/g,'');
  const list=$('chesscom-list');
  if (!username) { $('modal-error').textContent='Type a Chess.com username first.'; return; }
  $('modal-error').textContent=''; list.innerHTML='<div class="empty-list">Checking archives for “'+escapeHtml(username)+'”…</div>';
  try {
    const archivesRes=await fetch(`https://api.chess.com/pub/player/${username}/games/archives`);
    if (!archivesRes.ok) {
      if (archivesRes.status===404) throw Error(`Player “${username}” not found. Check the spelling.`);
      if (archivesRes.status===429) throw Error('Chess.com rate limit hit. Wait a minute and try again.');
      throw Error(`Chess.com returned ${archivesRes.status}. Try again in a moment.`);
    }
    const archives=await archivesRes.json();
    if (!archives.archives?.length) throw Error(`No game archives for “${username}”. Their games may be private.`);
    // Archives arrive oldest -> newest. Keep that order, combine, then newest-first at the end.
    const last=archives.archives.slice(-3);
    const month=last.at(-1)?.match(/(\d{4})\/(\d{2})$/)?.slice(1).join('-')||'latest month';
    list.innerHTML=`<div class="empty-list">Loading games from ${escapeHtml(month)} + ${last.length-1} earlier month(s)…</div>`;
    const chunks=await Promise.all(last.map(async url=>{
      const res=await fetch(url);
      if (!res.ok) throw Error(`Chess.com archive failed (${res.status}). Try again.`);
      return res.json();
    }));
    // Each month's games are oldest -> newest; combined stays oldest -> newest, so reverse once for newest-first.
    const games=chunks.flatMap(chunk=>chunk.games||[]).reverse().slice(0,25);
    if (!games.length) throw Error('No downloadable games in the last 3 months with PGN. Play a rated game, then retry — or paste the PGN manually.');
    chesscomGames=games;
    let html=`<div class="import-hint">Showing ${games.length} most recent. Click a game or its Analyze button.</div>`, lastGroup='';
    games.forEach((g,i)=>{
      const group=chesscomDayLabel(g.end_time);
      if (group!==lastGroup) { html+=`<div class="date-group">${escapeHtml(group)}</div>`; lastGroup=group; }
      const {title,meta}=chesscomLabel(g);
      html+=`<div class="saved-item"><button type="button" data-chesscom="${i}"><strong>${escapeHtml(title)}</strong><span>${escapeHtml(meta)}</span></button><button type="button" class="analyze-mini" data-chesscom="${i}">Analyze →</button></div>`;
    });
    list.innerHTML=html;
  } catch(error) {
    list.innerHTML='<div class="empty-list">Could not load games.</div>';
    $('modal-error').textContent=(error.message||'Network error.')+' If it keeps failing, open the game on Chess.com → Share → copy the PGN into Paste PGN. (Chess.com allows only public games; offline browsers also block the API.)';
  }
});
